$js = @'
(() => {
  const flow = document.querySelector('.og-flow');
  if (!flow) return {error:'no flow'};
  const row = flow.querySelector('.og-flow-row');
  const card = flow.querySelector('.og-flow-card');
  return {
    flowChildren: [...flow.children].map(e=>e.className),
    rowHTML: row ? row.outerHTML.slice(0, 1200) : null,
    cardHTML: card ? card.outerHTML.slice(0, 1200) : null
  };
})()
'@; $b = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($js)); agent-browser --session verify-afb193532731 eval -b $b --json 2>&1 | Select-Object -First 30

$js = @'
(() => {
  const q = s => document.querySelectorAll(s);
  const flow = document.querySelector('.og-flow');
  const rows = [...q('.og-flow-row')];
  const cards = [...q('.og-flow-card')];
  const arrows = q('.og-flow-arrow');
  const exp = [
    ['开发企业管理','房地产开发企业入网认证'],
    ['项目楼盘表','建立项目、楼幢与房源基础信息'],
    ['地名管理','项目地名命名备案'],
    ['价格备案','商品房销售价格备案'],
    ['预售许可','商品房预售许可申请、审核与证件发放'],
    ['合同网签','商品房买卖合同签订与备案'],
    ['预售资金监管','商品房预售资金入账与监管'],
    ['交付管理','商品房项目交付备案'],
    ['现售备案','商品房现房销售备案']
  ];
  const got = cards.map(c => [
    c.querySelector('.og-flow-card-title')?.textContent.trim(),
    c.querySelector('.og-flow-card-body')?.textContent.trim()
  ]);
  const idxs = cards.map(c => c.querySelector('.og-flow-card-index')?.textContent.trim());
  const textMatch = JSON.stringify(got) === JSON.stringify(exp);
  const firstCard = cards[0];
  const idx0 = firstCard?.querySelector('.og-flow-card-index');
  const csCard = firstCard ? getComputedStyle(firstCard) : null;
  const csIdx = idx0 ? getComputedStyle(idx0) : null;
  const btn = document.querySelector('.og-flow-action button') || document.querySelector('.og-flow-action');
  const rowCardCounts = rows.map(r => r.querySelectorAll('.og-flow-card').length);
  const rowArrowCounts = rows.map(r => r.querySelectorAll('.og-flow-arrow').length);
  return {
    hasFlow: !!flow,
    calloutCount: q('.og-callout').length,
    cardCount: cards.length,
    rowCount: rows.length,
    rowCardCounts,
    rowArrowCounts,
    totalArrows: arrows.length,
    indices: idxs,
    textMatch,
    got,
    buttonText: btn?.textContent.trim(),
    cardBorderTopColor: csCard?.borderTopColor,
    cardBorderTopWidth: csCard?.borderTopWidth,
    circleBg: csIdx?.backgroundColor,
    circleColor: csIdx?.color
  };
})()
'@; $b = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($js)); agent-browser --session verify-afb193532731 eval -b $b --json 2>&1 | Select-Object -First 30

$js = @'
(() => {
  const cards = [...document.querySelectorAll('.og-flow-card')];
  const vp = window.innerWidth;
  const rows = cards.map((c,i) => {
    const r = c.getBoundingClientRect();
    return {n:i+1, top:Math.round(r.top), left:Math.round(r.left), w:Math.round(r.width)};
  });
  const rowEls = [...document.querySelectorAll('.og-flow-row')].map(r=>({cls:r.className, top:Math.round(r.getBoundingClientRect().top), flexWrap:getComputedStyle(r).flexWrap, display:getComputedStyle(r).display}));
  return {viewportWidth:vp, cards:rows, rowEls};
})()
'@; $b = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($js)); agent-browser --session verify-afb193532731 eval -b $b --json 2>&1 | Select-Object -First 20

